on conflict (standard_code, clause) do update set title=excluded.title, requirement=excluded.requirement, evidence_tables=excluded.evidence_tables, basis=excluded.basis, metric_sql=excluded.metric_sql, threshold=excluded.threshold, points=excluded.points, level=excluded.level;
-- Điểm ICFS theo trại: tính metric_sql từng điều khoản (an toàn: chỉ chạy các SQL đã khai báo trong bảng, do QA/IT quản lý)
create or replace function icfs_score(p_farm text) returns table(clause text, title text, level text, points int, threshold text, value text, pass bool) language plpgsql security definer as $$
declare r record; v text; ok bool; num numeric; th text; begin
  for r in select * from standard_requirements where standard_code='ITRAN-STD' order by clause loop
    v := null; ok := null;
    if r.metric_sql is not null then begin execute r.metric_sql into v using p_farm; exception when others then v := 'ERR'; end; end if;
    th := coalesce(r.threshold,''); num := nullif(regexp_replace(coalesce(v,''),'[^0-9.\-]','','g'),'')::numeric;
    if v is null or v='ERR' then ok := null;
    elsif th like '≥%' then ok := num >= nullif(regexp_replace(th,'[^0-9.]','','g'),'')::numeric;
    elsif th like '≤%' then ok := num <= nullif(regexp_replace(th,'[^0-9.]','','g'),'')::numeric;
    elsif th like '=%' then ok := num = nullif(regexp_replace(th,'[^0-9.]','','g'),'')::numeric;
    elsif th like '>%' then ok := num > nullif(regexp_replace(th,'[^0-9.]','','g'),'')::numeric;
    else ok := true; end if;
    clause := r.clause; title := r.title; level := r.level; points := r.points; threshold := r.threshold; value := v; pass := ok; return next;
  end loop; end $$;
grant execute on function icfs_score(text) to app_user;
create or replace view v_icfs_summary as
select f.id as farm_id, f.name, s.total_points, s.got_points, round(100.0*s.got_points/nullif(s.total_points,0),0) as pct, s.critical_fail,
  case when s.critical_fail>0 then 'CHƯA ĐẠT' when 100.0*s.got_points/nullif(s.total_points,0)>=92 then 'VÀNG' when 100.0*s.got_points/nullif(s.total_points,0)>=80 then 'BẠC' when 100.0*s.got_points/nullif(s.total_points,0)>=60 then 'ĐỒNG' else 'CHƯA ĐẠT' end as level
from farms f cross join lateral (select coalesce(sum(points),0) as total_points, coalesce(sum(points) filter (where pass),0) as got_points, count(*) filter (where level='CRITICAL' and pass=false) as critical_fail from icfs_score(f.id)) s;
grant select on v_icfs_summary to app_user;
